return function(classname, super, ...)
    local superType = type(super)
    local cls
 
    if superType ~= "function" and superType ~= "table" then
        superType = nil
        super = nil
    end
 
    if super then
        cls = {}
        setmetatable(cls, {__index=super})
        cls.super = super
        -- if super.__table and not __table then
        --     __table = super.__table
        -- end
    else
        cls = {ctor = function() end}
    end

    local tables = {...}
    for i, v in pairs(tables) do
        for j, k in pairs(v) do
            cls[j] = k
        end
    end

    cls.ClassName = classname
    cls.__index = cls
    -- cls.__table = __table

    -- if __table then
    --     for i, v in pairs(__table) do
    --         cls[i] = v
    --     end
    -- end

    function cls.new(...)
        local instance = setmetatable({}, cls)
        instance.class = cls
        instance:ctor(...)
        if instance.Load then
            instance:Load(...)
        end
        return instance
    end
    return cls
end
